def grid4(a,b,c,d):
    return '<div style="display:grid;grid-template-columns:1fr 1fr;gap:20px">'+''.join([a,b,c,d])+'</div>'
def c4(h,ps,top):
    inner=''.join(f'<p style="font-size:24px;line-height:1.4;color:#4A5B69">{p}</p>' for p in ps)
    return f'<div style="display:flex;flex-direction:column;gap:8px;background:#FFFFFF;border:1px solid #D6DEE4;border-top:6px solid {top};border-radius:14px;padding:24px 28px"><h3 style="font-size:28px;font-weight:600">{h}</h3>{inner}</div>'
def hyp(id,n,name,H,W,B,A,notes):
    return sec(id,False,f'Méthode {n} · hypothèses et choix',name,grid4(c4('Hypothèses',H,'#7FC8F8'),c4('Pourquoi ces choix',W,'#0E8F73'),c4('Ce qui casse, et pourquoi',B,'#ED6965'),c4('Alternatives et améliorations',A,'#E3A008')),'Lecture méthodologique · '+FT,notes)
NEW={}
